    use_effect(move || {
        if let Some(t) = toast() {
            let mut sig = toast;
            spawn_local(async move {
                sleep(Duration::from_secs(5)).await;
                if sig().as_ref().map(|x| x.id) == Some(t.id) { sig.set(None); }
