    let toast_ctx = use_context::<ToastCtx>();
    let nav = use_navigator();
    let role = (auth.session)()
        .as_ref()
        .map(jwt_role)
        .unwrap_or_else(|| "Auditor".to_string());
    let is_admin = role == "Admin" || role == "Administrator";
    let is_coordinator = role == "Coordinator" || role == "Exam Coordinator";
    rsx! {
