use anyhow::{anyhow, Result};
use base64::Engine;
use chrono::Utc;
use serde::Serialize;
use sqlx::MySqlPool;
use tracing::info;

#[derive(Debug, Clone, Serialize)]
pub struct PrintOutput {
    pub output_type: String,
    pub mode: String,
    pub watermark: Option<String>,
    pub content: String,
}

#[derive(Clone)]
pub struct OutputService {
    pool: MySqlPool,
}

impl OutputService {
    pub fn new(pool: MySqlPool) -> Self {
        Self { pool }
    }

    pub async fn generate_print_output(
        &self,
        session_id: &str,
        output_type: &str,
        mode: &str,
        user_id: &str,
        is_admin: bool,
    ) -> Result<PrintOutput> {
        let watermark = if mode.eq_ignore_ascii_case("TestPrint") {
            Some(format!("TEST PRINT {}", Utc::now().format("%Y-%m-%d %H:%M:%S")))
        } else {
            None
        };

        if mode.eq_ignore_ascii_case("FinalPrint") {
            if !is_admin {
                let owned: Option<i64> = sqlx::query_scalar(
                    "SELECT 1 FROM exam_sessions WHERE id = ? AND created_by = ? LIMIT 1",
                )
                .bind(session_id)
                .bind(user_id)
                .fetch_optional(&self.pool)
                .await?;

                if owned.is_none() {
                    return Err(anyhow!("forbidden: cannot final-print another user's session"));
                }
            }

            sqlx::query("UPDATE exam_sessions SET locked_for_final_print = TRUE, status = 'FinalPrinted' WHERE id = ?")
                .bind(session_id)
                .execute(&self.pool)
                .await?;
        }

        let content = format!(
            "{} for session {} generated at {}",
            output_type,
            session_id,
            Utc::now().to_rfc3339()
        );

        let print_id = uuid::Uuid::new_v4().to_string();
        sqlx::query("INSERT INTO print_outputs (id, session_id, output_type, mode, watermark, payload, created_by) VALUES (?, ?, ?, ?, ?, ?, ?)")
            .bind(print_id)
            .bind(session_id)
            .bind(output_type)
            .bind(mode)
            .bind(watermark.clone())
            .bind(&content)
            .bind(user_id)
            .execute(&self.pool)
            .await?;

        info!(action = "generate_print_output", output_type = %output_type, mode = %mode, session_id = %session_id, "output generated");

        Ok(PrintOutput {
            output_type: output_type.to_string(),
            mode: mode.to_string(),
            watermark,
            content,
        })
    }

    pub fn mask_sensitive_id(value: &str) -> String {
        if value.len() <= 4 {
            return "****".to_string();
        }
        let suffix = &value[value.len() - 4..];
        format!("****{}", suffix)
    }

    pub fn export_csv_whitelisted(rows: &[serde_json::Value], fields: &[&str]) -> Result<String> {
        if fields.is_empty() {
            return Err(anyhow!("at least one field is required"));
        }

        let mut out = String::new();
        out.push_str(&fields.join(","));
        out.push('\n');

        for row in rows {
            let mut cols = Vec::with_capacity(fields.len());
            for field in fields {
                let val = row.get(*field).map(|v| v.to_string()).unwrap_or_else(|| "\"\"".to_string());
                cols.push(val.replace(',', " "));
            }
            out.push_str(&cols.join(","));
            out.push('\n');
        }

        Ok(out)
    }

    pub fn export_excel_like_tsv(rows: &[serde_json::Value], fields: &[&str]) -> Result<String> {
        if fields.is_empty() {
            return Err(anyhow!("at least one field is required"));
        }

        let mut out = String::new();
        out.push_str(&fields.join("\t"));
        out.push('\n');

        for row in rows {
            let mut cols = Vec::with_capacity(fields.len());
            for field in fields {
                cols.push(row.get(*field).and_then(|v| v.as_str()).unwrap_or_default().to_string());
            }
            out.push_str(&cols.join("\t"));
            out.push('\n');
        }

        Ok(out)
    }

    pub fn export_pdf_placeholder(document_title: &str, body: &str) -> String {
        // Minimal real PDF generation (single page, Helvetica).
        fn esc(s: &str) -> String {
            s.replace('\\', "\\\\").replace('(', "\\(").replace(')', "\\)")
        }

        let text = format!(
            "{}\n{}\nGenerated: {}",
            document_title,
            body,
            Utc::now().to_rfc3339()
        );
        let stream = format!(
            "BT /F1 12 Tf 50 770 Td ({}) Tj ET",
            esc(&text.replace('\n', " | "))
        );

        let obj1 = "1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n".to_string();
        let obj2 = "2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n".to_string();
        let obj3 = "3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>\nendobj\n".to_string();
        let obj4 = "4 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>\nendobj\n".to_string();
        let obj5 = format!(
            "5 0 obj\n<< /Length {} >>\nstream\n{}\nendstream\nendobj\n",
            stream.len(),
            stream
        );

        let mut pdf = Vec::<u8>::new();
        pdf.extend_from_slice(b"%PDF-1.4\n");
        let mut offsets = vec![0usize];
        for obj in [&obj1, &obj2, &obj3, &obj4, &obj5] {
            offsets.push(pdf.len());
            pdf.extend_from_slice(obj.as_bytes());
        }
        let xref_start = pdf.len();
        pdf.extend_from_slice(format!("xref\n0 {}\n", offsets.len()).as_bytes());
        pdf.extend_from_slice(b"0000000000 65535 f \n");
        for off in offsets.iter().skip(1) {
            pdf.extend_from_slice(format!("{off:010} 00000 n \n").as_bytes());
        }
        pdf.extend_from_slice(
            format!(
                "trailer\n<< /Size {} /Root 1 0 R >>\nstartxref\n{}\n%%EOF\n",
                offsets.len(),
                xref_start
            )
            .as_bytes(),
        );

        format!(
            "data:application/pdf;base64,{}",
            base64::engine::general_purpose::STANDARD.encode(pdf)
        )
    }
}

