use rocket::http::Status;
use rocket::serde::json::Json;
use rocket::{delete, get, post, put, State};

use sqlx::{MySql, MySqlPool, QueryBuilder};
use tracing::info;

use app_services::audit_service::AuditService;
use app_services::candidate_service::CandidateService;
use app_services::rbac_service::RbacService;

use crate::errors::{ApiError, ApiResult};
use crate::pagination::PaginationParams;
use crate::shared::{actor_user_id, audit, is_admin, ApiContext};

#[derive(Debug, serde::Deserialize)]
pub struct CreateCandidateRequest {
    pub candidate_id: String,
    pub date_of_birth: String,
    pub national_id: String,
    pub scanned_barcode: String,
    pub metadata_json: String,
}

#[derive(Debug, serde::Deserialize)]
pub struct UpdateCandidateRequest {
    pub scanned_barcode: String,
    pub metadata_json: String,
}

#[derive(Debug, serde::Deserialize)]
pub struct MergeCandidateRequest {
    pub left_candidate_id: String,
    pub right_candidate_id: String,
    pub similarity_score: f64,
}

#[derive(Debug, serde::Serialize, sqlx::FromRow)]
pub struct CandidateRow {
    pub id: String,
    pub encrypted_dob: String,
    pub national_id: String,
    pub scanned_barcode: String,
    pub metadata: serde_json::Value,
    pub created_by: String,
}

#[post("/candidates", data = "<payload>")]
pub async fn create_candidate(
    payload: Json<CreateCandidateRequest>,
    candidate_service: &State<CandidateService>,
    audit_service: &State<AuditService>,
    ctx: ApiContext,
) -> ApiResult<Status> {
    RbacService::require_manage_inventory(&ctx.actor.role).map_err(|_| ApiError::forbidden("role cannot create candidate"))?;
    let user_id = actor_user_id(&ctx)?;

    candidate_service
        .create_candidate(
            &payload.candidate_id,
            &payload.date_of_birth,
            &payload.national_id,
            &payload.scanned_barcode,
            &payload.metadata_json,
            user_id,
        )
        .await
        .map_err(|_| ApiError::conflict("candidate already exists or payload invalid"))?;

    let _ = audit_service
        .record_change(
            "candidates",
            &payload.candidate_id,
            "CREATE",
            None,
            Some(serde_json::json!({"candidate_id": payload.candidate_id})),
            user_id,
        )
        .await;

    info!(action = "create_candidate", candidate_id = %payload.candidate_id, "candidate created");
    audit(audit_service, &ctx, "create_candidate", "/api/v1/candidates").await;
    Ok(Status::Created)
}

#[get("/candidates?<page>&<limit>&<sort_by>&<sort_order>&<filter>")]
pub async fn list_candidates(
    pool: &State<MySqlPool>,
    audit_service: &State<AuditService>,
    ctx: ApiContext,
    page: Option<u32>,
    limit: Option<u32>,
    sort_by: Option<String>,
    sort_order: Option<String>,
    filter: Option<String>,
) -> ApiResult<Json<Vec<CandidateRow>>> {
    RbacService::require_manage_inventory(&ctx.actor.role).map_err(|_| ApiError::forbidden("role cannot list candidates"))?;
    let user_id = actor_user_id(&ctx)?;

    let params = PaginationParams {
        page,
        limit,
        sort_by,
        sort_order,
        filter,
    };
    let order = params.sort_order_sql();
    let col = match params.sort_by.as_deref() {
        Some("id") => "id",
        Some("scanned_barcode") => "scanned_barcode",
        Some("national_id") => "national_id",
        _ => "created_at",
    };

    let filter_value = params
        .filter
        .as_deref()
        .map(str::trim)
        .filter(|v| !v.is_empty())
        .map(|v| format!("%{}%", v));

    let mut qb = QueryBuilder::<MySql>::new(
        "SELECT id, encrypted_dob, national_id, scanned_barcode, metadata, created_by FROM candidates",
    );

    let mut has_where = false;
    if !is_admin(&ctx) {
        qb.push(" WHERE created_by = ").push_bind(user_id);
        has_where = true;
    }

    if let Some(ref like) = filter_value {
        if has_where {
            qb.push(" AND (");
        } else {
            qb.push(" WHERE (");
        }
        qb.push("id LIKE ")
            .push_bind(like.clone())
            .push(" OR scanned_barcode LIKE ")
            .push_bind(like.clone())
            .push(" OR national_id LIKE ")
            .push_bind(like.clone())
            .push(")");
    }

    qb.push(" ORDER BY ")
        .push(col)
        .push(" ")
        .push(order)
        .push(" LIMIT ")
        .push_bind(params.limit() as i64)
        .push(" OFFSET ")
        .push_bind(params.offset() as i64);

    let rows = qb
        .build_query_as::<CandidateRow>()
        .fetch_all(pool.inner())
        .await
        .map_err(|_| ApiError::internal("failed to list candidates"))?;

    audit(audit_service, &ctx, "list_candidates", "/api/v1/candidates").await;
    Ok(Json(rows))
}

#[get("/candidates/<id>")]
pub async fn get_candidate(
    id: &str,
    pool: &State<MySqlPool>,
    audit_service: &State<AuditService>,
    ctx: ApiContext,
) -> ApiResult<Json<CandidateRow>> {
    RbacService::require_manage_inventory(&ctx.actor.role).map_err(|_| ApiError::forbidden("role cannot read candidate"))?;
    let user_id = actor_user_id(&ctx)?;

    let row = if is_admin(&ctx) {
        sqlx::query_as::<_, CandidateRow>(
            "SELECT id, encrypted_dob, national_id, scanned_barcode, metadata, created_by FROM candidates WHERE id = ?",
        )
        .bind(id)
        .fetch_optional(pool.inner())
        .await
        .map_err(|_| ApiError::internal("failed to read candidate"))?
    } else {
        sqlx::query_as::<_, CandidateRow>(
            "SELECT id, encrypted_dob, national_id, scanned_barcode, metadata, created_by FROM candidates WHERE id = ? AND created_by = ?",
        )
        .bind(id)
        .bind(user_id)
        .fetch_optional(pool.inner())
        .await
        .map_err(|_| ApiError::internal("failed to read candidate"))?
    };

    let row = row.ok_or_else(|| ApiError::not_found("candidate not found"))?;
    audit(audit_service, &ctx, "get_candidate", "/api/v1/candidates/{id}").await;
    Ok(Json(row))
}

#[put("/candidates/<id>", data = "<payload>")]
pub async fn update_candidate(
    id: &str,
    payload: Json<UpdateCandidateRequest>,
    pool: &State<MySqlPool>,
    audit_service: &State<AuditService>,
    ctx: ApiContext,
) -> ApiResult<Status> {
    RbacService::require_manage_inventory(&ctx.actor.role).map_err(|_| ApiError::forbidden("role cannot update candidate"))?;
    let user_id = actor_user_id(&ctx)?;

    let result = if is_admin(&ctx) {
        sqlx::query("UPDATE candidates SET scanned_barcode = ?, metadata = CAST(? AS JSON) WHERE id = ?")
            .bind(&payload.scanned_barcode)
            .bind(&payload.metadata_json)
            .bind(id)
            .execute(pool.inner())
            .await
            .map_err(|_| ApiError::internal("failed to update candidate"))?
    } else {
        sqlx::query("UPDATE candidates SET scanned_barcode = ?, metadata = CAST(? AS JSON) WHERE id = ? AND created_by = ?")
            .bind(&payload.scanned_barcode)
            .bind(&payload.metadata_json)
            .bind(id)
            .bind(user_id)
            .execute(pool.inner())
            .await
            .map_err(|_| ApiError::internal("failed to update candidate"))?
    };

    if result.rows_affected() == 0 {
        return Err(ApiError::not_found("candidate not found"));
    }

    let _ = audit_service
        .record_change(
            "candidates",
            id,
            "UPDATE",
            None,
            Some(serde_json::json!({"scanned_barcode": payload.scanned_barcode})),
            user_id,
        )
        .await;

    audit(audit_service, &ctx, "update_candidate", "/api/v1/candidates/{id}").await;
    Ok(Status::Ok)
}

#[delete("/candidates/<id>")]
pub async fn delete_candidate(
    id: &str,
    pool: &State<MySqlPool>,
    audit_service: &State<AuditService>,
    ctx: ApiContext,
) -> ApiResult<Status> {
    RbacService::require_manage_inventory(&ctx.actor.role).map_err(|_| ApiError::forbidden("role cannot delete candidate"))?;
    let user_id = actor_user_id(&ctx)?;

    let result = if is_admin(&ctx) {
        sqlx::query("DELETE FROM candidates WHERE id = ?")
            .bind(id)
            .execute(pool.inner())
            .await
            .map_err(|_| ApiError::internal("failed to delete candidate"))?
    } else {
        sqlx::query("DELETE FROM candidates WHERE id = ? AND created_by = ?")
            .bind(id)
            .bind(user_id)
            .execute(pool.inner())
            .await
            .map_err(|_| ApiError::internal("failed to delete candidate"))?
    };

    if result.rows_affected() == 0 {
        return Err(ApiError::not_found("candidate not found"));
    }

    let _ = audit_service
        .record_change("candidates", id, "DELETE", None, None, user_id)
        .await;

    audit(audit_service, &ctx, "delete_candidate", "/api/v1/candidates/{id}").await;
    Ok(Status::NoContent)
}

#[post("/candidates/merge", data = "<payload>")]
pub async fn create_merge_candidate(
    payload: Json<MergeCandidateRequest>,
    pool: &State<MySqlPool>,
    audit_service: &State<AuditService>,
    ctx: ApiContext,
) -> ApiResult<Status> {
    RbacService::require_manage_inventory(&ctx.actor.role).map_err(|_| ApiError::forbidden("role cannot create merge candidate"))?;
    let user_id = actor_user_id(&ctx)?;

    sqlx::query("INSERT INTO merge_candidates (id, left_candidate_id, right_candidate_id, similarity_score, created_by) VALUES (?, ?, ?, ?, ?)")
        .bind(uuid::Uuid::new_v4().to_string())
        .bind(&payload.left_candidate_id)
        .bind(&payload.right_candidate_id)
        .bind(payload.similarity_score)
        .bind(user_id)
        .execute(pool.inner())
        .await
        .map_err(|_| ApiError::conflict("merge candidate already exists or invalid"))?;

    let _ = audit_service
        .record_change(
            "merge_candidates",
            &format!("{}:{}", payload.left_candidate_id, payload.right_candidate_id),
            "CREATE",
            None,
            Some(serde_json::json!({"similarity_score": payload.similarity_score})),
            user_id,
        )
        .await;

    audit(audit_service, &ctx, "create_merge_candidate", "/api/v1/candidates/merge").await;
    Ok(Status::Created)
}

