fn mask_sensitive_fields(row: &serde_json::Value) -> serde_json::Value {
    let mut row = row.clone();
    if let Some(obj) = row.as_object_mut() {
        for key in ["national_id", "id_number", "candidate_id"] {
            if let Some(value) = obj.get(key).and_then(|v| v.as_str()) {
                obj.insert(
                    key.to_string(),
                    serde_json::Value::String(OutputService::mask_sensitive_id(value)),
                );
            }
        }
    }
    row
}

