+        page,
+        limit,
+        sort_by,
+        sort_order,
+        filter,
+    };
+
+    let mut rows = reporting_service.materials_inventory().await.unwrap_or_else(|err| {
+        tracing::error!(error = %err, "materials_inventory query failed");
