                    })).collect::<Vec<Value>>()
                })
            }
            _ => return Err(anyhow!("unsupported output_type")),
        };

        Ok(serde_json::to_string_pretty(&payload)?)
    }

    pub fn mask_sensitive_id(value: &str) -> String {
        if value.len() <= 4 {
            return "****".to_string();
        }
        let suffix = &value[value.len() - 4..];
        format!("****{}", suffix)
    }

    pub fn export_csv_whitelisted(rows: &[serde_json::Value], fields: &[&str]) -> Result<String> {
        if fields.is_empty() {
            return Err(anyhow!("at least one field is required"));
        }

        let mut out = String::new();
        out.push_str(&fields.join(","));
        out.push('\n');

        for row in rows {
            let mut cols = Vec::with_capacity(fields.len());
            for field in fields {
                let val = row.get(*field).map(|v| v.to_string()).unwrap_or_else(|| "\"\"".to_string());
                cols.push(val.replace(',', " "));
            }
            out.push_str(&cols.join(","));
            out.push('\n');
        }

        Ok(out)
    }

    pub fn export_excel_like_tsv(rows: &[serde_json::Value], fields: &[&str]) -> Result<String> {
        if fields.is_empty() {
            return Err(anyhow!("at least one field is required"));
        }
        fn esc_xml(value: &str) -> String {
            value
                .replace('&', "&amp;")
                .replace('<', "&lt;")
                .replace('>', "&gt;")
                .replace('"', "&quot;")
                .replace('\'', "&apos;")
        }

        let mut xml = String::from(
            r#"<?xml version="1.0"?>
<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet"
 xmlns:o="urn:schemas-microsoft-com:office:office"
 xmlns:x="urn:schemas-microsoft-com:office:excel"
 xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">
<Worksheet ss:Name="Export">
<Table>"#,
        );

        xml.push_str("<Row>");
        for field in fields {
            xml.push_str(&format!(
                "<Cell><Data ss:Type=\"String\">{}</Data></Cell>",
                esc_xml(field)
            ));
        }
        xml.push_str("</Row>");

        for row in rows {
            xml.push_str("<Row>");
            for field in fields {
                let raw = row.get(*field).map(|v| {
                    if let Some(s) = v.as_str() {
                        s.to_string()
                    } else {
                        v.to_string()
                    }
                })
                .unwrap_or_default();
                xml.push_str(&format!(
                    "<Cell><Data ss:Type=\"String\">{}</Data></Cell>",
                    esc_xml(&raw)
                ));
            }
            xml.push_str("</Row>");
        }
        xml.push_str("</Table></Worksheet></Workbook>");

        Ok(format!(
            "data:application/vnd.ms-excel;base64,{}",
            base64::engine::general_purpose::STANDARD.encode(xml.as_bytes())
        ))
    }

